public function actionDelete($params) {
    $cert = Certificate::model()->findByPk($params['id']);
    if(!$cert) throw new NotFound();
    Account::model()->findByPk($cert->account_id); // permission check
    return ['success' => $cert->delete()];
}

public function actionImport($params) {
    if(empty($params['blobId']) || empty($params['email']))
        throw new InvalidArgumentException();
    $blob = Blob::findById($params['blobId']);
    $content = file_get_contents($blob->path());
    $success = PublicCertificate::import($content, [$params['email']]);
    return ['success' => $success];
}
